.wb-tablewrap{border:2px solid #E2571C;border-radius:8px;overflow:hidden;}
.wb-table{width:100%;border-collapse:collapse;font-size:13px;}
.wb-table th{background:#E2571C;color:#fff;padding:6px 10px;font-weight:700;text-align:left;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.wb-table td{padding:6px 10px;border-top:1px solid #f0c9a8;border-right:1px solid #f0c9a8;font-weight:600;}
.wb-table td:last-child,.wb-table th:last-child{border-right:none;}
.wb-pagetitle{font-size:19px;font-weight:800;color:#1a1a2e;border-bottom:3px solid #F5A623;padding-bottom:6px;margin-bottom:2px;letter-spacing:0.3px;}
.wb-pagesub{font-size:11px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:1px;margin-top:-6px;}
.wb-subhead{font-size:14.5px;font-weight:800;color:#E2571C;margin-top:2px;}
.wb-bullets{margin:0;padding-left:18px;font-size:13.5px;line-height:1.55;font-weight:600;color:#1a1a1a;}
.wb-bullets li{margin-bottom:4px;}
.wb-para{font-size:13.5px;line-height:1.55;font-weight:600;color:#1a1a1a;margin:0;}
.wb-wordgrid{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;padding:6px 4px;}
.wb-wordcard{width:230px;height:120px;flex:0 0 230px;border:2px dashed #F5A623;border-radius:12px;background:#fffaf0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;box-sizing:border-box;}
.wb-wordcard .wb-icon{width:36px;height:36px;color:#E2571C;opacity:0.55;}
.wb-wordcard .wb-word{font-size:17.5px;font-weight:800;color:#1a1a2e;letter-spacing:0.3px;text-align:center;padding:0 8px;}
.wb-wordcard .wb-marklbl{font-size:10px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:0.6px;}
.wb-chiplist{display:flex;flex-wrap:wrap;gap:10px;padding:4px 2px;justify-content:center;}
.wb-chip{border:2px solid #1a1a2e;border-radius:20px;padding:6px 16px;font-size:14px;font-weight:800;color:#1a1a2e;background:#fff;}
.wb-notebook{position:relative;height:100%;box-sizing:border-box;padding:14px 22px 14px 42px;font-family:'Poppins','Segoe UI',Arial,sans-serif;display:flex;flex-direction:column;overflow:hidden;}
.wb-notebook::before{content:'';position:absolute;left:34px;top:6px;bottom:6px;width:2.5px;background:#E2571C;opacity:0.6;border-radius:2px;}
.wb-nb-header{display:flex;justify-content:space-between;gap:20px;font-size:13px;font-weight:700;color:#1a1a2e;margin-bottom:10px;}
.wb-nb-header .fld{border-bottom:1.4px dotted #999;padding-bottom:3px;min-width:150px;}
.wb-nb-prompt{font-size:13px;font-weight:600;color:#1a1a1a;background:#fff8f3;border:1.6px dashed #E2571C;border-radius:8px;padding:7px 12px;margin-bottom:10px;line-height:1.4;}
.wb-nb-lines{flex:1;display:flex;flex-direction:column;justify-content:flex-start;}
.wb-nb-line{border-bottom:1.4px solid #cfd8e3;height:0;margin-bottom:26px;}
.wb-nb-line:last-child{margin-bottom:0;}

